window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-169aaf4520097591"]={"versions": [{"id": "FIG-169aaf4520097591", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Mathematisches Konzept- und Definitionsdiagramm (zweidimensionales, rechtshändiges kartesisches Koordinatensystem) innerhalb des AUTOSAR-Metamodells (<code>AUTOSAR_TR_GeneralBlueprintsSupplement</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Standardisierung der Achsenorientierung, Achsenbezeichnungen und Indizierungskonventionen für mehrdimensionale Kennfelder (<code>MAP</code>, <code>CUBOID</code>, <code>CURVE</code>) sowie deren Abbildung auf Datenstrukturen (<code>SwRecordLayout</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient als normative Referenz zur Vermeidung semantischer Inkonsistenzen an der Schnittstelle zwischen mathematischer Funktionsentwicklung (z. B. MATLAB/Simulink), AUTOSAR-Softwarekomponenten-Metamodell (<code>ApplicationDataType</code>, <code>SwRecordLayoutGroup</code>) und Kalibrierungs-Standards (ASAM MCD-2 MC / A2L, ASAM CDF).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Achsenentitäten:</strong></li>\n<li><code>AXIS 1</code> (Abszisse / x-Achse): Repräsentiert die primäre, unabhängige Eingangsvariable eines 2D-Kennfelds. Positive Achsenrichtung verläuft horizontal nach rechts.</li>\n<li><code>AXIS 2</code> (Ordinate / y-Achse): Repräsentiert die sekundäre, unabhängige Eingangsvariable. Positive Achsenrichtung verläuft vertikal nach oben.</li>\n<li><strong>Gitter & Stützstellen (Grid Points):</strong></li>\n<li>Diskrete ganzzahlige Achsenskalen (im Schaubild beispielhaft Wertebereich $1 \\dots 5$).</li>\n<li>Entspricht im Metamodell den Stützstellenvektoren (<code>SwAxisCont</code>, <code>FixAxisMetadata</code> oder extern referenzierten <code>AXIS_PTS</code>).</li>\n<li><strong>Datenpunkt / Arbeitspunkt:</strong></li>\n<li>Explizit annotierter Punkt bei $(x=3,\\, y=2)$. Repräsentiert das Wertepaar $(\\text{AXIS 1} = 3,\\, \\text{AXIS 2} = 2)$ zur Lokalisierung eines Funktionswertes $z = f(x, y)$ in einer 2D-Matrix.</li>\n<li><strong>Metamodell-Beziehungen & Stereotypen:</strong></li>\n<li>Assoziiert mit «atpVariation»-fähigen Elementen im Umfeld von <code>SwRecordLayout</code> und <code>SwRecordLayoutVaxis</code>.</li>\n<li>Kardinalitäten im 2D-Kennfeld (<code>MAP</code>): Exakt zwei Input-Achsen (<code>AXIS 1</code> mit Kardinalität 1, <code>AXIS 2</code> mit Kardinalität 1), die bijektiv auf die Dimensionen einer Werte-Tabelle (<code>VAL_BLK</code> / <code>FNC_VALUES</code>) referenzieren.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>(Statische Koordinatendefinition; relevant für die Laufzeit-Auswertung im SWC/BSW-Kontext)</em></p>\n<ol class=\"fig-list\">\n<li><strong>Signalerfassung:</strong> Eingangssignale für Abszisse ($x$) und Ordinate ($y$) werden zyklisch über RTE-Ports eingelesen (z. B. <code>Rte_Read_&lt;p&gt;_&lt;o&gt;</code>).</li>\n<li><strong>Stützstellensuche (Axis Search):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Lokalisierung des Intervalls auf <code>AXIS 1</code> ($x_k \\le x < x_{k+1}$) via Intervallsuche (Binary Search oder Even-Spacing-Berechnung).</li>\n<li>Parallele bzw. sequentielle Intervallsuche auf <code>AXIS 2</code> ($y_m \\le y < y_{m+1}$).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bilineare Interpolation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abruf der vier umschließenden Matrixstützstellen: $f(x_k, y_m)$, $f(x_{k+1}, y_m)$, $f(x_k, y_{m+1})$, $f(x_{k+1}, y_{m+1})$.</li>\n<li>Berechnung des interpolierten Ausgangswertes über arithmetische BSW-Bibliotheken (z. B. <code>Bfx_Intrp2D</code> oder herstellerspezifische Math-Routinen).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Grenzwerte & Extrapolation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sättigung/Clipping bei Überschreitung des Definitionsbereichs ($x > x_{max}$, $y > y_{max}$) gemäß den in <code>SwRecordLayout</code> und <code>CompuMethod</code> hinterlegten Intervallregeln.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Speicherlayout & Matrix-Serialisierung (Row-Major vs. Column-Major):</strong></li>\n<li><code>AXIS 1</code> bezeichnet per Definition die $x$-Dimension, <code>AXIS 2</code> die $y$-Dimension.</li>\n<li>In C-Code-Implementierungen (<code>Rte_Type.h</code> / Kennfeld-Arrays) ist zwingend auf die Dimensionierung zu achten: Ein 2D-C-Array <code>Table[Y_SIZE][X_SIZE]</code> adressiert Elemente über <code>Table[y][x]</code>. Eine Verwechslung von Zeilen- und Spaltenindex führt zur Transponierung des Kennfelds im NVM/Flash und damit zu falschen Interpolationsergebnissen.</li>\n<li><strong>A2L-Generierung & ASAM MCD-2 MC Konformität:</strong></li>\n<li>Kalibrierwerkzeuge (z. B. CANape, INCA) werten <code>INDEX_INCR</code>, <code>ROW_DIR</code> bzw. <code>COLUMN_DIR</code> im <code>RECORD_LAYOUT</code> aus. Die Zuordnung von <code>AXIS_PTS_REF</code> zu <code>AXIS 1</code> und <code>AXIS 2</code> muss exakt mit der AUTOSAR-Metamodell-Definition übereinstimmen.</li>\n<li><strong>API-Vertrag für BSW-Math-Bibliotheken:</strong></li>\n<li>Schnittstellen wie <code>Bfx_Intrp2D</code> erwarten die Argumente strikt in der Reihenfolge <code>(Input_Axis1, Input_Axis2, ...)</code>; Vertauschen der Parameter invertiert die Achsenabhängigkeit der Kennfeldfunktion.</li>\n</ul>"}, {"id": "FIG-281ae65a6d6deb44", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Mathematisches Konzept- und Definitionsdiagramm (zweidimensionales, rechtshändiges kartesisches Koordinatensystem) innerhalb des AUTOSAR-Metamodells (<code>AUTOSAR_TR_GeneralBlueprintsSupplement</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Standardisierung der Achsenorientierung, Achsenbezeichnungen und Indizierungskonventionen für mehrdimensionale Kennfelder (<code>MAP</code>, <code>CUBOID</code>, <code>CURVE</code>) sowie deren Abbildung auf Datenstrukturen (<code>SwRecordLayout</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient als normative Referenz zur Vermeidung semantischer Inkonsistenzen an der Schnittstelle zwischen mathematischer Funktionsentwicklung (z. B. MATLAB/Simulink), AUTOSAR-Softwarekomponenten-Metamodell (<code>ApplicationDataType</code>, <code>SwRecordLayoutGroup</code>) und Kalibrierungs-Standards (ASAM MCD-2 MC / A2L, ASAM CDF).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Achsenentitäten:</strong></li>\n<li><code>AXIS 1</code> (Abszisse / x-Achse): Repräsentiert die primäre, unabhängige Eingangsvariable eines 2D-Kennfelds. Positive Achsenrichtung verläuft horizontal nach rechts.</li>\n<li><code>AXIS 2</code> (Ordinate / y-Achse): Repräsentiert die sekundäre, unabhängige Eingangsvariable. Positive Achsenrichtung verläuft vertikal nach oben.</li>\n<li><strong>Gitter & Stützstellen (Grid Points):</strong></li>\n<li>Diskrete ganzzahlige Achsenskalen (im Schaubild beispielhaft Wertebereich $1 \\dots 5$).</li>\n<li>Entspricht im Metamodell den Stützstellenvektoren (<code>SwAxisCont</code>, <code>FixAxisMetadata</code> oder extern referenzierten <code>AXIS_PTS</code>).</li>\n<li><strong>Datenpunkt / Arbeitspunkt:</strong></li>\n<li>Explizit annotierter Punkt bei $(x=3,\\, y=2)$. Repräsentiert das Wertepaar $(\\text{AXIS 1} = 3,\\, \\text{AXIS 2} = 2)$ zur Lokalisierung eines Funktionswertes $z = f(x, y)$ in einer 2D-Matrix.</li>\n<li><strong>Metamodell-Beziehungen & Stereotypen:</strong></li>\n<li>Assoziiert mit «atpVariation»-fähigen Elementen im Umfeld von <code>SwRecordLayout</code> und <code>SwRecordLayoutVaxis</code>.</li>\n<li>Kardinalitäten im 2D-Kennfeld (<code>MAP</code>): Exakt zwei Input-Achsen (<code>AXIS 1</code> mit Kardinalität 1, <code>AXIS 2</code> mit Kardinalität 1), die bijektiv auf die Dimensionen einer Werte-Tabelle (<code>VAL_BLK</code> / <code>FNC_VALUES</code>) referenzieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>(Statische Koordinatendefinition; relevant für die Laufzeit-Auswertung im SWC/BSW-Kontext)</em></p>\n<ol class=\"fig-list\">\n<li><strong>Signalerfassung:</strong> Eingangssignale für Abszisse ($x$) und Ordinate ($y$) werden zyklisch über RTE-Ports eingelesen (z. B. <code>Rte_Read_&lt;p&gt;_&lt;o&gt;</code>).</li>\n<li><strong>Stützstellensuche (Axis Search):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Lokalisierung des Intervalls auf <code>AXIS 1</code> ($x_k \\le x < x_{k+1}$) via Intervallsuche (Binary Search oder Even-Spacing-Berechnung).</li>\n<li>Parallele bzw. sequentielle Intervallsuche auf <code>AXIS 2</code> ($y_m \\le y < y_{m+1}$).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bilineare Interpolation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abruf der vier umschließenden Matrixstützstellen: $f(x_k, y_m)$, $f(x_{k+1}, y_m)$, $f(x_k, y_{m+1})$, $f(x_{k+1}, y_{m+1})$.</li>\n<li>Berechnung des interpolierten Ausgangswertes über arithmetische BSW-Bibliotheken (z. B. <code>Bfx_Intrp2D</code> oder herstellerspezifische Math-Routinen).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Grenzwerte & Extrapolation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sättigung/Clipping bei Überschreitung des Definitionsbereichs ($x > x_{max}$, $y > y_{max}$) gemäß den in <code>SwRecordLayout</code> und <code>CompuMethod</code> hinterlegten Intervallregeln.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Speicherlayout & Matrix-Serialisierung (Row-Major vs. Column-Major):</strong></li>\n<li><code>AXIS 1</code> bezeichnet per Definition die $x$-Dimension, <code>AXIS 2</code> die $y$-Dimension.</li>\n<li>In C-Code-Implementierungen (<code>Rte_Type.h</code> / Kennfeld-Arrays) ist zwingend auf die Dimensionierung zu achten: Ein 2D-C-Array <code>Table[Y_SIZE][X_SIZE]</code> adressiert Elemente über <code>Table[y][x]</code>. Eine Verwechslung von Zeilen- und Spaltenindex führt zur Transponierung des Kennfelds im NVM/Flash und damit zu falschen Interpolationsergebnissen.</li>\n<li><strong>A2L-Generierung & ASAM MCD-2 MC Konformität:</strong></li>\n<li>Kalibrierwerkzeuge (z. B. CANape, INCA) werten <code>INDEX_INCR</code>, <code>ROW_DIR</code> bzw. <code>COLUMN_DIR</code> im <code>RECORD_LAYOUT</code> aus. Die Zuordnung von <code>AXIS_PTS_REF</code> zu <code>AXIS 1</code> und <code>AXIS 2</code> muss exakt mit der AUTOSAR-Metamodell-Definition übereinstimmen.</li>\n<li><strong>API-Vertrag für BSW-Math-Bibliotheken:</strong></li>\n<li>Schnittstellen wie <code>Bfx_Intrp2D</code> erwarten die Argumente strikt in der Reihenfolge <code>(Input_Axis1, Input_Axis2, ...)</code>; Vertauschen der Parameter invertiert die Achsenabhängigkeit der Kennfeldfunktion.</li>\n</ul>"}, {"id": "FIG-f0b61515394c3f12", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Mathematisches Konzept- und Definitionsdiagramm (zweidimensionales, rechtshändiges kartesisches Koordinatensystem) innerhalb des AUTOSAR-Metamodells (<code>AUTOSAR_TR_GeneralBlueprintsSupplement</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Standardisierung der Achsenorientierung, Achsenbezeichnungen und Indizierungskonventionen für mehrdimensionale Kennfelder (<code>MAP</code>, <code>CUBOID</code>, <code>CURVE</code>) sowie deren Abbildung auf Datenstrukturen (<code>SwRecordLayout</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient als normative Referenz zur Vermeidung semantischer Inkonsistenzen an der Schnittstelle zwischen mathematischer Funktionsentwicklung (z. B. MATLAB/Simulink), AUTOSAR-Softwarekomponenten-Metamodell (<code>ApplicationDataType</code>, <code>SwRecordLayoutGroup</code>) und Kalibrierungs-Standards (ASAM MCD-2 MC / A2L, ASAM CDF).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Achsenentitäten:</strong></li>\n<li><code>AXIS 1</code> (Abszisse / x-Achse): Repräsentiert die primäre, unabhängige Eingangsvariable eines 2D-Kennfelds. Positive Achsenrichtung verläuft horizontal nach rechts.</li>\n<li><code>AXIS 2</code> (Ordinate / y-Achse): Repräsentiert die sekundäre, unabhängige Eingangsvariable. Positive Achsenrichtung verläuft vertikal nach oben.</li>\n<li><strong>Gitter & Stützstellen (Grid Points):</strong></li>\n<li>Diskrete ganzzahlige Achsenskalen (im Schaubild beispielhaft Wertebereich $1 \\dots 5$).</li>\n<li>Entspricht im Metamodell den Stützstellenvektoren (<code>SwAxisCont</code>, <code>FixAxisMetadata</code> oder extern referenzierten <code>AXIS_PTS</code>).</li>\n<li><strong>Datenpunkt / Arbeitspunkt:</strong></li>\n<li>Explizit annotierter Punkt bei $(x=3,\\, y=2)$. Repräsentiert das Wertepaar $(\\text{AXIS 1} = 3,\\, \\text{AXIS 2} = 2)$ zur Lokalisierung eines Funktionswertes $z = f(x, y)$ in einer 2D-Matrix.</li>\n<li><strong>Metamodell-Beziehungen & Stereotypen:</strong></li>\n<li>Assoziiert mit «atpVariation»-fähigen Elementen im Umfeld von <code>SwRecordLayout</code> und <code>SwRecordLayoutVaxis</code>.</li>\n<li>Kardinalitäten im 2D-Kennfeld (<code>MAP</code>): Exakt zwei Input-Achsen (<code>AXIS 1</code> mit Kardinalität 1, <code>AXIS 2</code> mit Kardinalität 1), die bijektiv auf die Dimensionen einer Werte-Tabelle (<code>VAL_BLK</code> / <code>FNC_VALUES</code>) referenzieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>(Statische Koordinatendefinition; relevant für die Laufzeit-Auswertung im SWC/BSW-Kontext)</em></p>\n<ol class=\"fig-list\">\n<li><strong>Signalerfassung:</strong> Eingangssignale für Abszisse ($x$) und Ordinate ($y$) werden zyklisch über RTE-Ports eingelesen (z. B. <code>Rte_Read_&lt;p&gt;_&lt;o&gt;</code>).</li>\n<li><strong>Stützstellensuche (Axis Search):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Lokalisierung des Intervalls auf <code>AXIS 1</code> ($x_k \\le x < x_{k+1}$) via Intervallsuche (Binary Search oder Even-Spacing-Berechnung).</li>\n<li>Parallele bzw. sequentielle Intervallsuche auf <code>AXIS 2</code> ($y_m \\le y < y_{m+1}$).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bilineare Interpolation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abruf der vier umschließenden Matrixstützstellen: $f(x_k, y_m)$, $f(x_{k+1}, y_m)$, $f(x_k, y_{m+1})$, $f(x_{k+1}, y_{m+1})$.</li>\n<li>Berechnung des interpolierten Ausgangswertes über arithmetische BSW-Bibliotheken (z. B. <code>Bfx_Intrp2D</code> oder herstellerspezifische Math-Routinen).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Grenzwerte & Extrapolation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sättigung/Clipping bei Überschreitung des Definitionsbereichs ($x > x_{max}$, $y > y_{max}$) gemäß den in <code>SwRecordLayout</code> und <code>CompuMethod</code> hinterlegten Intervallregeln.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Speicherlayout & Matrix-Serialisierung (Row-Major vs. Column-Major):</strong></li>\n<li><code>AXIS 1</code> bezeichnet per Definition die $x$-Dimension, <code>AXIS 2</code> die $y$-Dimension.</li>\n<li>In C-Code-Implementierungen (<code>Rte_Type.h</code> / Kennfeld-Arrays) ist zwingend auf die Dimensionierung zu achten: Ein 2D-C-Array <code>Table[Y_SIZE][X_SIZE]</code> adressiert Elemente über <code>Table[y][x]</code>. Eine Verwechslung von Zeilen- und Spaltenindex führt zur Transponierung des Kennfelds im NVM/Flash und damit zu falschen Interpolationsergebnissen.</li>\n<li><strong>A2L-Generierung & ASAM MCD-2 MC Konformität:</strong></li>\n<li>Kalibrierwerkzeuge (z. B. CANape, INCA) werten <code>INDEX_INCR</code>, <code>ROW_DIR</code> bzw. <code>COLUMN_DIR</code> im <code>RECORD_LAYOUT</code> aus. Die Zuordnung von <code>AXIS_PTS_REF</code> zu <code>AXIS 1</code> und <code>AXIS 2</code> muss exakt mit der AUTOSAR-Metamodell-Definition übereinstimmen.</li>\n<li><strong>API-Vertrag für BSW-Math-Bibliotheken:</strong></li>\n<li>Schnittstellen wie <code>Bfx_Intrp2D</code> erwarten die Argumente strikt in der Reihenfolge <code>(Input_Axis1, Input_Axis2, ...)</code>; Vertauschen der Parameter invertiert die Achsenabhängigkeit der Kennfeldfunktion.</li>\n</ul>"}, {"id": "FIG-3e84aa2599df087c", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Mathematisches Konzept- und Definitionsdiagramm (zweidimensionales, rechtshändiges kartesisches Koordinatensystem) innerhalb des AUTOSAR-Metamodells (<code>AUTOSAR_TR_GeneralBlueprintsSupplement</code>).</li>\n<li><strong>Technischer Zweck:</strong> Formale Standardisierung der Achsenorientierung, Achsenbezeichnungen und Indizierungskonventionen für mehrdimensionale Kennfelder (<code>MAP</code>, <code>CUBOID</code>, <code>CURVE</code>) sowie deren Abbildung auf Datenstrukturen (<code>SwRecordLayout</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> Dient als normative Referenz zur Vermeidung semantischer Inkonsistenzen an der Schnittstelle zwischen mathematischer Funktionsentwicklung (z. B. MATLAB/Simulink), AUTOSAR-Softwarekomponenten-Metamodell (<code>ApplicationDataType</code>, <code>SwRecordLayoutGroup</code>) und Kalibrierungs-Standards (ASAM MCD-2 MC / A2L, ASAM CDF).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Achsenentitäten:</strong></li>\n<li><code>AXIS 1</code> (Abszisse / x-Achse): Repräsentiert die primäre, unabhängige Eingangsvariable eines 2D-Kennfelds. Positive Achsenrichtung verläuft horizontal nach rechts.</li>\n<li><code>AXIS 2</code> (Ordinate / y-Achse): Repräsentiert die sekundäre, unabhängige Eingangsvariable. Positive Achsenrichtung verläuft vertikal nach oben.</li>\n<li><strong>Gitter & Stützstellen (Grid Points):</strong></li>\n<li>Diskrete ganzzahlige Achsenskalen (im Schaubild beispielhaft Wertebereich $1 \\dots 5$).</li>\n<li>Entspricht im Metamodell den Stützstellenvektoren (<code>SwAxisCont</code>, <code>FixAxisMetadata</code> oder extern referenzierten <code>AXIS_PTS</code>).</li>\n<li><strong>Datenpunkt / Arbeitspunkt:</strong></li>\n<li>Explizit annotierter Punkt bei $(x=3,\\, y=2)$. Repräsentiert das Wertepaar $(\\text{AXIS 1} = 3,\\, \\text{AXIS 2} = 2)$ zur Lokalisierung eines Funktionswertes $z = f(x, y)$ in einer 2D-Matrix.</li>\n<li><strong>Metamodell-Beziehungen & Stereotypen:</strong></li>\n<li>Assoziiert mit «atpVariation»-fähigen Elementen im Umfeld von <code>SwRecordLayout</code> und <code>SwRecordLayoutVaxis</code>.</li>\n<li>Kardinalitäten im 2D-Kennfeld (<code>MAP</code>): Exakt zwei Input-Achsen (<code>AXIS 1</code> mit Kardinalität 1, <code>AXIS 2</code> mit Kardinalität 1), die bijektiv auf die Dimensionen einer Werte-Tabelle (<code>VAL_BLK</code> / <code>FNC_VALUES</code>) referenzieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>(Statische Koordinatendefinition; relevant für die Laufzeit-Auswertung im SWC/BSW-Kontext)</em></p>\n<ol class=\"fig-list\">\n<li><strong>Signalerfassung:</strong> Eingangssignale für Abszisse ($x$) und Ordinate ($y$) werden zyklisch über RTE-Ports eingelesen (z. B. <code>Rte_Read_&lt;p&gt;_&lt;o&gt;</code>).</li>\n<li><strong>Stützstellensuche (Axis Search):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Lokalisierung des Intervalls auf <code>AXIS 1</code> ($x_k \\le x < x_{k+1}$) via Intervallsuche (Binary Search oder Even-Spacing-Berechnung).</li>\n<li>Parallele bzw. sequentielle Intervallsuche auf <code>AXIS 2</code> ($y_m \\le y < y_{m+1}$).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bilineare Interpolation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abruf der vier umschließenden Matrixstützstellen: $f(x_k, y_m)$, $f(x_{k+1}, y_m)$, $f(x_k, y_{m+1})$, $f(x_{k+1}, y_{m+1})$.</li>\n<li>Berechnung des interpolierten Ausgangswertes über arithmetische BSW-Bibliotheken (z. B. <code>Bfx_Intrp2D</code> oder herstellerspezifische Math-Routinen).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Grenzwerte & Extrapolation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sättigung/Clipping bei Überschreitung des Definitionsbereichs ($x > x_{max}$, $y > y_{max}$) gemäß den in <code>SwRecordLayout</code> und <code>CompuMethod</code> hinterlegten Intervallregeln.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Speicherlayout & Matrix-Serialisierung (Row-Major vs. Column-Major):</strong></li>\n<li><code>AXIS 1</code> bezeichnet per Definition die $x$-Dimension, <code>AXIS 2</code> die $y$-Dimension.</li>\n<li>In C-Code-Implementierungen (<code>Rte_Type.h</code> / Kennfeld-Arrays) ist zwingend auf die Dimensionierung zu achten: Ein 2D-C-Array <code>Table[Y_SIZE][X_SIZE]</code> adressiert Elemente über <code>Table[y][x]</code>. Eine Verwechslung von Zeilen- und Spaltenindex führt zur Transponierung des Kennfelds im NVM/Flash und damit zu falschen Interpolationsergebnissen.</li>\n<li><strong>A2L-Generierung & ASAM MCD-2 MC Konformität:</strong></li>\n<li>Kalibrierwerkzeuge (z. B. CANape, INCA) werten <code>INDEX_INCR</code>, <code>ROW_DIR</code> bzw. <code>COLUMN_DIR</code> im <code>RECORD_LAYOUT</code> aus. Die Zuordnung von <code>AXIS_PTS_REF</code> zu <code>AXIS 1</code> und <code>AXIS 2</code> muss exakt mit der AUTOSAR-Metamodell-Definition übereinstimmen.</li>\n<li><strong>API-Vertrag für BSW-Math-Bibliotheken:</strong></li>\n<li>Schnittstellen wie <code>Bfx_Intrp2D</code> erwarten die Argumente strikt in der Reihenfolge <code>(Input_Axis1, Input_Axis2, ...)</code>; Vertauschen der Parameter invertiert die Achsenabhängigkeit der Kennfeldfunktion.</li>\n</ul>"}], "trans": [{"from": "FIG-169aaf4520097591", "to": "FIG-281ae65a6d6deb44", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-281ae65a6d6deb44", "to": "FIG-f0b61515394c3f12", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f0b61515394c3f12", "to": "FIG-3e84aa2599df087c", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
